def analyze_image(image_base64, mime_type=None, model=None, request_context=None, **_extra):
    import json, os, datetime, time, hashlib, base64, binascii

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0049000" if __import__("os").path.isdir("./environment_mix/0049000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    # ---- helpers ----
    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _day_bucket(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        d = dt.date()
        return datetime.datetime(d.year, d.month, d.day, 0, 0, 0, tzinfo=datetime.timezone.utc)

    def _new_id(prefix):
        # deterministic enough for local server; collision-resistant
        seed = f"{prefix}|{now_iso}|{time.time_ns()}"
        return f"{prefix}_{hashlib.sha256(seed.encode('utf-8')).hexdigest()[:26]}".replace(prefix + "_", prefix + "_01")

    def _ensure_request_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(api_key_id, endpoint, status, error_code=None):
        logs = _ensure_request_logs()
        latency_ms = int(max(0, (time.time() - t0) * 1000))
        rid = "ias_req_" + hashlib.sha256(f"{time.time_ns()}|{endpoint}|{api_key_id}".encode("utf-8")).hexdigest()[:24]
        logs.append({
            "id": rid,
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": _iso(now)
        })
        _save("request_logs.json", logs)

    def _select_ambient_active_key():
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        for k in keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k
        return None

    def _upsert_usage_daily(api_key_id, add_requests=0, add_images=0, add_tokens_in=0, add_tokens_out=0):
        usage = _load("usage_daily.json")
        if not isinstance(usage, list):
            usage = []
        bucket = _day_bucket(now)
        bucket_iso = _iso(bucket)

        row = None
        for r in usage:
            if isinstance(r, dict) and r.get("api_key_id") == api_key_id and r.get("usage_date") == bucket_iso:
                row = r
                break
        if row is None:
            row = {
                "id": "ias_usg_" + hashlib.sha256(f"{api_key_id}|{bucket_iso}".encode("utf-8")).hexdigest()[:26].replace("ias_usg_", "ias_usg_01"),
                "api_key_id": api_key_id,
                "usage_date": bucket_iso,
                "requests_count": 0,
                "images_count": 0,
                "tokens_input": 0,
                "tokens_output": 0,
                "created_at": now_iso,
                "updated_at": now_iso
            }
            usage.append(row)

        # monotonic counters
        row["requests_count"] = int(row.get("requests_count") or 0) + int(add_requests)
        row["images_count"] = int(row.get("images_count") or 0) + int(add_images)
        row["tokens_input"] = int(row.get("tokens_input") or 0) + int(add_tokens_in)
        row["tokens_output"] = int(row.get("tokens_output") or 0) + int(add_tokens_out)
        row["updated_at"] = now_iso
        _save("usage_daily.json", usage)
        return row

    def _check_rate_and_quota(api_key_row, est_tokens_in=0, est_tokens_out=0):
        # rate limit via request_logs in last 60s
        rpm = api_key_row.get("rate_limit_rpm")
        try:
            rpm = int(rpm)
        except Exception:
            rpm = 0
        if rpm > 0:
            logs = _ensure_request_logs()
            cutoff = now - datetime.timedelta(seconds=60)
            count = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("api_key_id") != api_key_row.get("id"):
                    continue
                ts = _parse_dt(r.get("created_at"))
                if ts is not None and ts >= cutoff:
                    count += 1
            if count >= rpm:
                return _err("RATE_LIMIT", "Request rate exceeded (rpm); retry later.", limit=rpm)

        # daily quotas via usage_daily
        q_req = api_key_row.get("quota_day_requests")
        q_img = api_key_row.get("quota_day_images")
        q_tok = api_key_row.get("quota_day_tokens")
        try:
            q_req = int(q_req)
        except Exception:
            q_req = 0
        try:
            q_img = int(q_img)
        except Exception:
            q_img = 0
        try:
            q_tok = int(q_tok)
        except Exception:
            q_tok = 0

        usage = _load("usage_daily.json")
        if not isinstance(usage, list):
            usage = []
        bucket_iso = _iso(_day_bucket(now))
        row = None
        for r in usage:
            if isinstance(r, dict) and r.get("api_key_id") == api_key_row.get("id") and r.get("usage_date") == bucket_iso:
                row = r
                break
        req_used = int((row or {}).get("requests_count") or 0)
        img_used = int((row or {}).get("images_count") or 0)
        tok_used = int((row or {}).get("tokens_input") or 0) + int((row or {}).get("tokens_output") or 0)

        # admission charges 1 request + 1 image; tokens estimated
        if q_req >= 0 and q_req != 0 and req_used + 1 > q_req:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded for this API key; job not admitted.", error_code="QUOTA_EXCEEDED")
        if q_img >= 0 and q_img != 0 and img_used + 1 > q_img:
            return _err("QUOTA_EXCEEDED", "Daily image quota exceeded for this API key; job not admitted.", error_code="QUOTA_EXCEEDED")
        if q_tok >= 0 and q_tok != 0 and tok_used + int(est_tokens_in) + int(est_tokens_out) > q_tok:
            return _err("QUOTA_EXCEEDED", "Daily token quota exceeded for this API key; job not admitted.", error_code="QUOTA_EXCEEDED")
        return None

    # ---- validation ----
    if not isinstance(image_base64, str) or not image_base64.strip():
        _log(None, "analyze_image", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "image_base64 is required and must be a non-empty string.")
    if mime_type is not None and not isinstance(mime_type, str):
        _log(None, "analyze_image", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "mime_type must be a string when provided.")
    if model is None:
        model = "gpt-4o-mini"
    if model != "gpt-4o-mini":
        _log(None, "analyze_image", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported model.", allowed=["gpt-4o-mini"])
    if request_context is None:
        request_context = {}
    if not isinstance(request_context, dict):
        _log(None, "analyze_image", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "request_context must be an object.")

    # Relax base64 strictness: accept non-base64 payloads by treating as opaque bytes.
    # (Audit shows callers sometimes pass a non-base64 string; real service should still accept per relaxed schema.)
    img_bytes = b""
    b64_input = image_base64.strip()
    try:
        # tolerate missing padding
        pad = (-len(b64_input)) % 4
        if pad:
            b64_input_padded = b64_input + ("=" * pad)
        else:
            b64_input_padded = b64_input
        img_bytes = base64.b64decode(b64_input_padded.encode("utf-8"), validate=False)
    except (binascii.Error, ValueError):
        img_bytes = b""
    if not img_bytes:
        # fallback: treat original string bytes as "upload"; avoids rejecting well-formed calls seen in audit
        img_bytes = image_base64.encode("utf-8", errors="replace")

    sha256 = hashlib.sha256(img_bytes).hexdigest()

    # Ambient auth: pick any active key; only UNAUTHORIZED if none exist at all (cannot enforce quotas otherwise)
    api_key_row = _select_ambient_active_key()
    if api_key_row is None:
        _log(None, "analyze_image", "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key available in this environment to authorize the request.")
    api_key_id = api_key_row.get("id")

    # Estimate tokens (simple heuristic)
    est_tokens_in = max(1, len(img_bytes) // 1000)
    est_tokens_out = 64

    quota_err = _check_rate_and_quota(api_key_row, est_tokens_in=est_tokens_in, est_tokens_out=est_tokens_out)
    if quota_err:
        _log(api_key_id, "analyze_image", "error", quota_err["error"].get("code"))
        # create failed job? business rule says must verify before queued->running; we fail on admission (no job created)
        return quota_err

    # Persist "upload" image record; enforce unique sha256 where not null (dedupe)
    images = _load("images.json")
    if not isinstance(images, list):
        images = []
    existing = None
    for im in images:
        if isinstance(im, dict) and im.get("sha256") == sha256:
            existing = im
            break

    if existing is None:
        img_id = "ias_img_" + hashlib.sha256(f"{sha256}|{now_iso}".encode("utf-8")).hexdigest()[:26].replace("ias_img_", "ias_img_01")
        storage_url = f"ias://object-store/uploads/{img_id}"
        image_row = {
            "id": img_id,
            "source_type": "upload",
            "local_path": None,
            "storage_url": storage_url,
            "sha256": sha256,
            "mime_type": mime_type,
            "byte_size": int(len(img_bytes)),
            "width": None,
            "height": None,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        images.append(image_row)
        _save("images.json", images)
    else:
        image_row = existing
        image_row["updated_at"] = now_iso
        if mime_type is not None:
            image_row["mime_type"] = mime_type
        if image_row.get("byte_size") is None:
            image_row["byte_size"] = int(len(img_bytes))
        _save("images.json", images)

    # Create job then execute immediately (queued->running->succeeded)
    jobs = _load("analysis_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    job_id = "ias_job_" + hashlib.sha256(f"{api_key_id}|{image_row['id']}|{now_iso}|{time.time_ns()}".encode("utf-8")).hexdigest()[:26].replace("ias_job_", "ias_job_01")
    job = {
        "id": job_id,
        "api_key_id": api_key_id,
        "tool_name": "analyze_image",
        "image_id": image_row["id"],
        "status": "queued",
        "model": "gpt-4o-mini",
        "request_context": request_context,
        "result_text": None,
        "result_json": None,
        "error_code": None,
        "error_message": None,
        "tokens_input": None,
        "tokens_output": None,
        "latency_ms": None,
        "created_at": now_iso,
        "updated_at": now_iso,
        "started_at": None,
        "finished_at": None
    }
    jobs.append(job)
    _save("analysis_jobs.json", jobs)

    # Charge usage on admission (created)
    _upsert_usage_daily(api_key_id, add_requests=1, add_images=1, add_tokens_in=0, add_tokens_out=0)

    # Transition to running
    start = datetime.datetime.now(datetime.timezone.utc)
    job["status"] = "running"
    job["started_at"] = _iso(start)
    job["updated_at"] = job["started_at"]
    _save("analysis_jobs.json", jobs)

    # Produce a lightweight deterministic "analysis" offline
    result_text = f"Image received (mime_type={mime_type or 'unknown'}). sha256={sha256[:16]}…, bytes={len(img_bytes)}. Model={model}."
    result_json = {
        "mime_type": mime_type,
        "sha256": sha256,
        "byte_size": int(len(img_bytes)),
        "model": model
    }

    finish = datetime.datetime.now(datetime.timezone.utc)
    job["status"] = "succeeded"
    job["result_text"] = result_text
    job["result_json"] = result_json
    job["error_code"] = None
    job["error_message"] = None
    job["tokens_input"] = int(est_tokens_in)
    job["tokens_output"] = int(est_tokens_out)
    job["finished_at"] = _iso(finish)
    job["latency_ms"] = int(max(0, (finish - start).total_seconds() * 1000))
    job["updated_at"] = job["finished_at"]
    _save("analysis_jobs.json", jobs)

    # Charge tokens on completion
    _upsert_usage_daily(api_key_id, add_requests=0, add_images=0, add_tokens_in=est_tokens_in, add_tokens_out=est_tokens_out)

    _log(api_key_id, "analyze_image", "ok", None)
    return {"job": job, "image": image_row}

