        tok_used = int((row or {}).get("tokens_input") or 0) + int((row or {}).get("tokens_output") or 0)

        if q_req >= 0 and q_req != 0 and req_used + 1 > q_req:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded for this API key; job not admitted.", error_code="QUOTA_EXCEEDED")
