        request_context = {}
    if not isinstance(request_context, dict):
        _log(None, "analyze_image_from_path", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "request_context must be an object.")

    # normalize path and enforce policy, but do NOT require OS file existence (datastore may contain paths not present)
    norm = os.path.normpath(local_path.strip())
    if not os.path.isabs(norm):
        _log(None, "analyze_image_from_path", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "local_path must be an absolute path per server policy.", local_path=local_path)

    parts = [p for p in norm.split(os.sep) if p]
    if ".." in parts:
        # per business rule: create failed job with IMAGE_LOAD_FAILED
        path_ok = False
        policy_reason = "Local path contains traversal '..' and was rejected by allowlist policy."
    else:
        denied_prefixes = [os.sep + "proc", os.sep + "sys", os.sep + "dev"]
        if any(norm == p or norm.startswith(p + os.sep) for p in denied_prefixes):
            path_ok = False
            policy_reason = f"Local path denied by policy (blocked prefix {denied_prefixes[[norm == p or norm.startswith(p + os.sep) for p in denied_prefixes].index(True)]})."
        else:
            path_ok = True
            policy_reason = None

    api_key_row = _select_ambient_active_key()
    if api_key_row is None:
        _log(None, "analyze_image_from_path", "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key available in this environment to authorize the request.")
    api_key_id = api_key_row.get("id")

    # quotas checked before queued->running; we'll admit and/or immediately fail depending on path policy
    est_tokens_in = 10
    est_tokens_out = 64
    quota_err = _check_rate_and_quota(api_key_row, est_tokens_in=est_tokens_in, est_tokens_out=est_tokens_out)
