        _log(api_key_id, "analyze_image_from_path", "error", quota_err["error"].get("code"))
        return quota_err

    # Create image row (source_type local_path). Enforce unique sha256 only when we have one; we won't hash file bytes.
    images = _load("images.json")
    if not isinstance(images, list):
        images = []
    img_id = "ias_img_" + hashlib.sha256(f"local|{norm}|{now_iso}|{time.time_ns()}".encode("utf-8")).hexdigest()[:26].replace("ias_img_", "ias_img_01")
    image_row = {
        "id": img_id,
        "source_type": "local_path",
        "local_path": norm,
        "storage_url": None,
        "sha256": None,
        "mime_type": None,
        "byte_size": None,
        "width": None,
        "height": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    images.append(image_row)
    _save("images.json", images)

    # Create job
    jobs = _load("analysis_jobs.json")
    if not isinstance(jobs, list):
        jobs = []
