def list_analysis_jobs(api_key, status=None, tool_name=None, model=None, api_key_id=None, image_id=None, created_after=None, created_before=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, hashlib, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0049000" if __import__("os").path.isdir("./environment_mix/0049000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("UNAUTHORIZED", "API key is required.")
    allowed_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    allowed_tool = {"analyze_image", "analyze_image_from_path"}
    if status is not None and status not in allowed_status:
        return _err("VALIDATION_ERROR", "Invalid status filter.", allowed=sorted(allowed_status))
    if tool_name is not None and tool_name not in allowed_tool:
        return _err("VALIDATION_ERROR", "Invalid tool_name filter.", allowed=sorted(allowed_tool))
    if model is not None and model != "gpt-4o-mini":
        return _err("VALIDATION_ERROR", "Invalid model filter.", allowed=["gpt-4o-mini"])
    if api_key_id is not None and not isinstance(api_key_id, str):
        return _err("VALIDATION_ERROR", "api_key_id must be a string.")
    if image_id is not None and not isinstance(image_id, str):
        return _err("VALIDATION_ERROR", "image_id must be a string.")
    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200.")
    if page_token is not None and not isinstance(page_token, str):
        return _err("VALIDATION_ERROR", "page_token must be a string.")

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string.")
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc)
        except Exception:
            return _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string.")

    ca = _parse_dt(created_after, "created_after")
    if isinstance(ca, dict) and "error" in ca:
        return ca
    cb = _parse_dt(created_before, "created_before")
    if isinstance(cb, dict) and "error" in cb:
        return cb

    # Authenticate: match api_key to api_keys.id OR api_keys.key_hash (client-visible value or id).
    api_keys = _load("api_keys.json")
    key_row = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key or k.get("key_hash") == api_key:
            key_row = k
            break
    if key_row is None or key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key missing/invalid or revoked.")

    caller_key_id = key_row.get("id")

    # api_key_id filter only allowed when equals caller
    if api_key_id is not None and api_key_id != caller_key_id:
        return _err("UNAUTHORIZED", "Not allowed to filter by a different api_key_id.")

    jobs = _load("analysis_jobs.json")

    # Pagination token: we use created_at cursor (exclusive) + id for tie-breaker: token = "<created_at>|<id>"
    cursor_created = None
    cursor_id = None
    if page_token:
        if "|" not in page_token:
            return _err("VALIDATION_ERROR", "Invalid page_token.")
        a, b = page_token.split("|", 1)
        try:
            if a.endswith("Z"):
                a2 = a[:-1] + "+00:00"
            else:
                a2 = a
            cursor_created = datetime.datetime.fromisoformat(a2).astimezone(datetime.timezone.utc)
            cursor_id = b
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid page_token.")

    def _job_created_dt(j):
        s = j.get("created_at")
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    # Filter: visible to caller -> jobs with api_key_id == caller_key_id only
    filtered = []
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if j.get("api_key_id") != caller_key_id:
            continue
        if status is not None and j.get("status") != status:
            continue
        if tool_name is not None and j.get("tool_name") != tool_name:
            continue
        if model is not None and j.get("model") != model:
            continue
        if api_key_id is not None and j.get("api_key_id") != api_key_id:
            continue
        if image_id is not None and j.get("image_id") != image_id:
            continue
        cdt = _job_created_dt(j)
        if ca is not None and (cdt is None or cdt < ca):
            continue
        if cb is not None and (cdt is None or cdt > cb):
            continue
        # cursor
        if cursor_created is not None and cdt is not None:
            # newest first; page_token refers to last item from previous page
            # include only items strictly older than cursor, or same time but id < cursor_id lexicographically
            if cdt > cursor_created:
                continue
            if cdt == cursor_created and isinstance(j.get("id"), str) and isinstance(cursor_id, str) and j.get("id") >= cursor_id:
                continue
        filtered.append(j)

    # Sort newest first by created_at then id desc
    def _sort_key(j):
        cdt = _job_created_dt(j)
        # None should go last
        if cdt is None:
            cdt = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (cdt, j.get("id") or "")
    filtered.sort(key=_sort_key, reverse=True)

    total = len(filtered)
    page = filtered[:page_size]
    has_more = total > len(page)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = f"{last.get('created_at')}|{last.get('id')}"

    # Observable dynamics: touch api key updated_at; upsert usage_daily updated_at (no counter increments for reads)
    key_row["updated_at"] = now_iso
    _save("api_keys.json", api_keys)
    usage = _load("usage_daily.json")
    # ensure today's bucket exists and update updated_at
    bucket = datetime.datetime(now.year, now.month, now.day, 0, 0, 0, tzinfo=datetime.timezone.utc)
    bucket_iso = bucket.isoformat().replace("+00:00", "Z")
    u = None
    for row in usage:
        if isinstance(row, dict) and row.get("api_key_id") == caller_key_id and row.get("usage_date") == bucket_iso:
            u = row
            break
    if u is None:
        u = {
            "id": f"uday_{now.strftime('%Y%m%d%H%M%S')}_{hashlib.sha256((caller_key_id+bucket_iso).encode('utf-8')).hexdigest()[:16]}",
            "api_key_id": caller_key_id,
            "usage_date": bucket_iso,
            "requests_count": 0,
            "images_count": 0,
            "tokens_input": 0,
            "tokens_output": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        usage.append(u)
    else:
        u["updated_at"] = now_iso
    _save("usage_daily.json", usage)

    return {
        "jobs": page,
        "meta": {
            "total": total,
            "page_size": page_size,
            "has_more": has_more,
            "next_page_token": next_cursor,
        },
    }

