        if active_match is not None:
            return active_match, None
        if any_match is not None:
            return None, _err(
                "UNAUTHORIZED",
                "API key is revoked; cancellation requires an active key.",
                api_key_id=any_match.get("id"),
            )
        return None, _err("UNAUTHORIZED", "API key is missing or invalid.")

    # Validate inputs
    if not isinstance(id, str) or not id.strip():
        _log(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id must be a non-empty string.")
    id = id.strip()

    if reason is not None and not isinstance(reason, str):
        _log(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "reason must be a string when provided.")

    key, auth_err = _find_key(api_key)
    if auth_err:
        _log(auth_err["error"].get("api_key_id"), "error", auth_err["error"]["code"])
        return auth_err

    jobs = _load("analysis_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    idx = None
    job = None
    for i, r in enumerate(jobs):
        if isinstance(r, dict) and r.get("id") == id:
            idx = i
            job = r
            break

    if job is None:
        _log(key.get("id"), "not_found", "NOT_FOUND")
        return _err("NOT_FOUND", "Analysis job not found.", id=id)

    # Visibility: job is visible if api_key_id is null OR matches caller key id.
    job_key_id = job.get("api_key_id")
    if job_key_id is not None and job_key_id != key.get("id"):
        _log(key.get("id"), "not_found", "NOT_FOUND")
        return _err("NOT_FOUND", "Analysis job not found.", id=id)

    status = job.get("status")
    terminal = status in ("succeeded", "failed", "cancelled")
    if terminal:
        # Idempotent: return unchanged
        _log(key.get("id"), "ok", None)
        return {"analysis_job": job}

    # Only queued/running are cancellable by lifecycle rules.
    if status not in ("queued", "running"):
        _log(key.get("id"), "error", "INVALID_TRANSITION")
        return _err(
            "INVALID_TRANSITION",
            f"Job cannot be cancelled from status '{status}'.",
            id=id,
            status=status,
        )

    # Transition to cancelled, set finished_at, latency if possible.
    updated = dict(job)
    updated["status"] = "cancelled"
    updated["updated_at"] = _iso(now)
    updated["finished_at"] = _iso(now)

    started_at = _parse_dt(updated.get("started_at"))
    if started_at is not None:
        latency_ms = int(max(0, (now - started_at).total_seconds() * 1000))
        updated["latency_ms"] = latency_ms

    # Store cancellation reason without leaking secrets; put into error_message for auditing.
    if isinstance(reason, str) and reason.strip():
        msg = reason.strip()
        if len(msg) > 500:
            msg = msg[:500]
        updated["error_message"] = f"Cancelled: {msg}"
    else:
        updated["error_message"] = "Cancelled by client request."

    # Keep error_code null for cancelled; ensure invariants.
    updated["error_code"] = None
    updated["result_text"] = updated.get("result_text")
    updated["result_json"] = updated.get("result_json")

    jobs[idx] = updated
    _save("analysis_jobs.json", jobs)

    _log(key.get("id"), "ok", None)
    return {"analysis_job": updated}

