                    return None, _err("UNAUTHORIZED", "API key is revoked or inactive.")
                return k, None
        return None, _err("UNAUTHORIZED", "Missing or invalid API key.")

    def _decode_token(tok):
        if tok is None:
            return 0, None
        if not isinstance(tok, str) or not tok.strip():
            return None, _err("VALIDATION_ERROR", "page_token must be a non-empty string when provided.")
        try:
            raw = base64.urlsafe_b64decode(tok.encode("utf-8") + b"===")
            data = json.loads(raw.decode("utf-8"))
            off = data.get("offset")
            if not isinstance(off, int) or off < 0:
                return None, _err("VALIDATION_ERROR", "Invalid page_token.")
            return off, None
        except Exception:
            return None, _err("VALIDATION_ERROR", "Invalid page_token.")

    def _encode_token(off):
        payload = json.dumps({"offset": off}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        _log(None, "list_images", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if source_type is not None and source_type not in ("upload", "local_path"):
        _log(None, "list_images", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "source_type must be one of: upload, local_path.")
    if sha256 is not None and not isinstance(sha256, str):
        _log(None, "list_images", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sha256 must be a string when provided.")
    if mime_type is not None and not isinstance(mime_type, str):
        _log(None, "list_images", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "mime_type must be a string when provided.")
    if created_after is not None and (_parse_dt(created_after) is None):
        _log(None, "list_images", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "created_after must be an RFC3339 date-time string when provided.")
    if created_before is not None and (_parse_dt(created_before) is None):
        _log(None, "list_images", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "created_before must be an RFC3339 date-time string when provided.")

    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        _log(None, "list_images", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200.")

    offset, e = _decode_token(page_token)
    if e:
        _log(None, "list_images", "error", "VALIDATION_ERROR")
        return e

    key_row, e = _auth_key(api_key.strip())
    if e:
        _log(None, "list_images", "error", "UNAUTHORIZED")
        return e

    # Visibility model: images are visible if referenced by any job for this api_key_id
    jobs = _load("analysis_jobs.json")
    if not isinstance(jobs, list):
        jobs = []
    visible_image_ids = set()
    for j in jobs:
        if isinstance(j, dict) and j.get("api_key_id") == key_row.get("id") and isinstance(j.get("image_id"), str):
            visible_image_ids.add(j["image_id"])

    images = _load("images.json")
    if not isinstance(images, list):
        images = []

    ca = _parse_dt(created_after) if created_after is not None else None
    cb = _parse_dt(created_before) if created_before is not None else None
    if ca and ca.tzinfo is None:
        ca = ca.replace(tzinfo=datetime.timezone.utc)
    if cb and cb.tzinfo is None:
        cb = cb.replace(tzinfo=datetime.timezone.utc)

    def _created_dt(img):
        dt = _parse_dt(img.get("created_at"))
        if dt and dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt

    # Filter
    rows = []
    for img in images:
        if not isinstance(img, dict):
            continue
        if img.get("id") not in visible_image_ids:
            continue
        if source_type is not None and img.get("source_type") != source_type:
            continue
        if sha256 is not None and img.get("sha256") != sha256:
            continue
        if mime_type is not None and img.get("mime_type") != mime_type:
            continue
        cdt = _created_dt(img)
        if ca and cdt and cdt < ca:
            continue
        if ca and cdt is None:
            continue
        if cb and cdt and cdt > cb:
            continue
        if cb and cdt is None:
            continue
        rows.append(img)

    # Sort newest first by created_at (fallback to id)
    rows.sort(key=lambda r: (r.get("created_at") is not None, r.get("created_at") or "", r.get("id") or ""), reverse=True)

    total = len(rows)
    start = offset
    end = min(total, start + page_size)
    page = rows[start:end]
    has_more = end < total
    next_token = _encode_token(end) if has_more else None

    _log(key_row.get("id"), "list_images", "ok")
    return {
        "images": page,
        "total": total,
        "page_size": page_size,
        "has_more": has_more,
        "next_page_token": next_token
    }

def get_image(api_key, id, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0049000" if __import__("os").path.isdir("./environment_mix/0049000") else "/app/database")
    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _ensure_request_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _log(api_key_id, status, error_code=None):
        logs = _ensure_request_logs()
        latency_ms = int(max(0, (time.time() - t0) * 1000))
        rid = "ias_req_" + hashlib.sha256(
            f"{time.time_ns()}|get_image|{api_key_id}|{id}".encode("utf-8")
        ).hexdigest()[:24]
        logs.append(
            {
                "id": rid,
                "endpoint": "get_image",
                "api_key_id": api_key_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": latency_ms,
                "created_at": _iso(now),
            }
        )
        _save("request_logs.json", logs)

    def _find_key(api_key_value):
        # Authenticate by matching client-visible value OR id. Never compare against key_hash.
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None, _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        v = api_key_value.strip()

        active_match = None
        any_match = None
        for k in keys:
            if not isinstance(k, dict):
                continue
            if v == k.get("id"):
                any_match = k
                if k.get("status") == "active":
                    active_match = k
                    break

        if active_match is not None:
            return active_match, None
        if any_match is not None:
            return None, _err(
                "UNAUTHORIZED",
                "API key is revoked; requests require an active key.",
                api_key_id=any_match.get("id"),
            )
        return None, _err("UNAUTHORIZED", "API key is missing or invalid.")

    # Validate inputs
    if not isinstance(id, str) or not id.strip():
        _log(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id must be a non-empty string.")
    id = id.strip()

    key, auth_err = _find_key(api_key)
    if auth_err:
        _log(auth_err["error"].get("api_key_id"), "error", auth_err["error"]["code"])
        return auth_err

    images = _load("images.json")
    if not isinstance(images, list):
        images = []
    img = None
    for r in images:
        if isinstance(r, dict) and r.get("id") == id:
            img = r
            break

    if img is None:
        _log(key.get("id"), "not_found", "NOT_FOUND")
        return _err("NOT_FOUND", "Image not found.", id=id)

    # Visibility: image is visible if it is referenced by any job visible to this key
    # (job api_key_id is null or matches key). This matches typical storage scoping.
    jobs = _load("analysis_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    visible = False
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if j.get("image_id") != id:
            continue
        jk = j.get("api_key_id")
        if jk is None or jk == key.get("id"):
            visible = True
            break

    if not visible:
        _log(key.get("id"), "not_found", "NOT_FOUND")
        return _err("NOT_FOUND", "Image not found.", id=id)

    _log(key.get("id"), "ok", None)
    return {"image": img}

def get_current_identity(api_key, usage_date=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0049000" if __import__("os").path.isdir("./environment_mix/0049000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _log(api_key_id, endpoint, status, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int(max(0, (time.time() - t0) * 1000))
        logs.append({
            "id": "req_" + hashlib.sha256((str(now.timestamp()) + "|" + endpoint + "|" + str(api_key_id)).encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": _iso(now)
        })
        _save("request_logs.json", logs)

    def _auth_key(api_key_value):
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        for k in keys:
            if not isinstance(k, dict):
                continue
            if api_key_value in (k.get("id"), k.get("key_hash")):
                if k.get("status") != "active":
                    return None, _err("UNAUTHORIZED", "API key is revoked or inactive.")
                return k, None
        return None, _err("UNAUTHORIZED", "Missing or invalid API key.")

    def _parse_date(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            # YYYY-MM-DD
            d = datetime.date.fromisoformat(s)
            return datetime.datetime(d.year, d.month, d.day, 0, 0, 0, tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        _log(None, "get_current_identity", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if usage_date is not None and _parse_date(usage_date) is None:
        _log(None, "get_current_identity", "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "usage_date must be YYYY-MM-DD when provided.")

    key_row, e = _auth_key(api_key.strip())
    if e:
        _log(None, "get_current_identity", "error", "UNAUTHORIZED")
        return e

    day_bucket = _parse_date(usage_date) if usage_date is not None else datetime.datetime(now.year, now.month, now.day, 0, 0, 0, tzinfo=datetime.timezone.utc)

    usage = _load("usage_daily.json")
    if not isinstance(usage, list):
        usage = []

    bucket_iso = _iso(day_bucket)
    urow = None
    for r in usage:
        if isinstance(r, dict) and r.get("api_key_id") == key_row.get("id") and r.get("usage_date") == bucket_iso:
            urow = r
            break

    if urow is None:
        urow = {
            "requests_count": 0,
            "images_count": 0,
            "tokens_input": 0,
            "tokens_output": 0
        }

    # Rate-limit snapshot (RPM) using request logs in last 60s
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    window_start = now - datetime.timedelta(seconds=60)
    rpm = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != key_row.get("id"):
            continue
        ts = r.get("created_at")
        if not isinstance(ts, str):
            continue
        try:
            ss = ts.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= window_start:
                rpm += 1
        except Exception:
            continue

    limits = {
        "quota_day_requests": key_row.get("quota_day_requests"),
        "quota_day_images": key_row.get("quota_day_images"),
        "quota_day_tokens": key_row.get("quota_day_tokens"),
        "rate_limit_rpm": key_row.get("rate_limit_rpm"),
    }
    usage_snapshot = {
        "usage_date": bucket_iso,
        "requests_count": urow.get("requests_count", 0),
        "images_count": urow.get("images_count", 0),
        "tokens_input": urow.get("tokens_input", 0),
        "tokens_output": urow.get("tokens_output", 0),
        "requests_last_60s": rpm
    }
    remaining = {
        "quota_day_requests_remaining": None if limits["quota_day_requests"] is None else max(0, int(limits["quota_day_requests"]) - int(usage_snapshot["requests_count"])),
        "quota_day_images_remaining": None if limits["quota_day_images"] is None else max(0, int(limits["quota_day_images"]) - int(usage_snapshot["images_count"])),
        "quota_day_tokens_remaining": None if limits["quota_day_tokens"] is None else max(0, int(limits["quota_day_tokens"]) - int(usage_snapshot["tokens_input"]) - int(usage_snapshot["tokens_output"])),
        "rate_limit_rpm_remaining": None if limits["rate_limit_rpm"] is None else max(0, int(limits["rate_limit_rpm"]) - int(rpm)),
    }

    identity = {
        "api_key": {
            "id": key_row.get("id"),
            "label": key_row.get("label"),
            "status": key_row.get("status"),
            "created_at": key_row.get("created_at"),
            "updated_at": key_row.get("updated_at"),
            "revoked_at": key_row.get("revoked_at"),
        },
        "limits": limits,
        "usage": usage_snapshot,
        "remaining": remaining
    }

    _log(key_row.get("id"), "get_current_identity", "ok")
    return {"identity": identity}
